**第 1 步：用户态读写骨架（x64，MSVC 编译）**
```cpp
// cheat_min.h
#pragma once
#include <windows.h>
#include <tlhelp32.h>
#include <cstdint>

struct Proc {
    HANDLE h = nullptr;
    DWORD pid = 0;
    uintptr_t base = 0;

    bool attach(const wchar_t* name) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        PROCESSENTRY32W pe{ sizeof(pe) };
        for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe)) {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        }
        CloseHandle(snap);
        if (!pid) return false;
        h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!h) return false;
        HANDLE ms = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
        MODULEENTRY32W me{ sizeof(me) };
        if (Module32FirstW(ms, &me)) base = (uintptr_t)me.modBaseAddr;
        CloseHandle(ms);
        return base != 0;
    }

    template <class T> bool rd(uintptr_t addr, T& out) {
        SIZE_T n = 0;
        return ReadProcessMemory(h, (LPCVOID)addr, &out, sizeof(T), &n) && n == sizeof(T);
    }
    uintptr_t ptr(uintptr_t addr) { uintptr_t v = 0; rd(addr, v); return v; }
    uintptr_t chain(uintptr_t addr, std::initializer_list<uintptr_t> offs) {
        uintptr_t p = ptr(addr);
        for (auto it = offs.begin(); it != offs.end(); ++it) {
            if (!p) return 0;
            if (std::next(it) == offs.end()) return p + *it;
            p = ptr(p + *it);
        }
        return 0;
    }
};
```

