struct Matrix4x4 { float m[4][4]; };

inline bool WorldToScreen(const Vec3& w, const Matrix4x4& vp, int sw, int sh, Vec2& out) {
    float x = w.x*vp.m[0][0] + w.y*vp.m[1][0] + w.z*vp.m[2][0] + vp.m[3][0];
    float y = w.x*vp.m[0][1] + w.y*vp.m[1][1] + w.z*vp.m[2][1] + vp.m[3][1];
    float z = w.x*vp.m[0][2] + w.y*vp.m[1][2] + w.z*vp.m[2][2] + vp.m[3][2];
    float ww= w.x*vp.m[0][3] + w.y*vp.m[1][3] + w.z*vp.m[2][3] + vp.m[3][3];
