```javascript
// coin_scan.js
function scanDword(val) {
    var ranges = Process.enumerateRanges('rw-');
    var hits = [];
    var pat = ptr(val).toString(16).padStart(8, '0');
    var bytes = [];
    for (var i = 6; i >= 0; i -= 2) bytes.push('0x' + pat.substr(i, 2));
    var sig = bytes.join(' ');
    ranges.forEach(function (r) {
        try {
            Memory.scanSync(r.base, r.size, sig).forEach(function (m) {
                hits.push(m.address);
            });
        } catch (e) {}
    });
    return hits;
}

var pid = Process.id;
console.log('pid=' + pid);
var cur = 12580; // 换成当前金币
var hits = scanDword(cur);
console.log('hits(' + cur + ')=' + hits.length);
hits.slice(0, 30).forEach(function (a) { console.log(' ' + a); });
