        for (DWORD i = 0; i < need / sizeof(HMODULE); ++i) {
            wchar_t name[MAX_PATH]{};
            GetModuleBaseNameW(h, mods[i], name, MAX_PATH);
            MODULEINFO mi{};
            GetModuleInformation(h, mods[i], &mi, sizeof(mi));
            printf("%-40ws base=%p size=0x%08X\n", name, mi.lpBaseOfDll, mi.SizeOfImage);
        }
    }
    return 0;
}
