```cpp
// 目标：ReadProcessMemory 拿 [进程名].exe 的基址与 GWorld/GNames
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

struct ModInfo { uintptr_t base; size_t size; };

static ModInfo GetModuleBase(DWORD pid, const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    ModInfo r{ 0, 0 };
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, name) == 0) { r.base = (uintptr_t)me.modBaseAddr; r.size = me.modBaseSize; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return r;
}

// 多级指针链：base + 第一级偏移 -> 解引用 -> 第二级 ... 
template<typename T>
static T Rpm(HANDLE h, uintptr_t addr) {
    T v{};
    ReadProcessMemory(h, (LPCVOID)addr, &v, sizeof(T), nullptr);
    return v;
}

// 示例：GWorld = *(base + [GWorldOffset])
// UWorld -> OwningGameInstance -> LocalPlayers[0] -> PlayerController -> AcknowledgedPawn -> ...
uintptr_t ResolveChain(HANDLE h, uintptr_t base, const std::vector<uintptr_t>& chain) {
    uintptr_t p = base;
    for (size_t i = 0; i < chain.size(); ++i) {
        p = Rpm<uintptr_t>(h, p + chain[i]);
        if (!p || p < 0x10000) return 0;
    }
    return p;
}
```

