bool WorldToScreen(const FMatrix& m, const FVector& w, int sw, int sh, FVector2D& out) {
    float vw = m.M[3][0]*w.X + m.M[3][1]*w.Y + m.M[3][2]*w.Z + m.M[3][3];
    if (vw < 0.001f) return false;
    float vx = m.M[0][0]*w.X + m.M[0][1]*w.Y + m.M[0][2]*w.Z + m.M[0][3];
    float vy = m.M[1][0]*w.X + m.M[1][1]*w.Y + m.M[1][2]*w.Z + m.M[1][3];
    out.X = (sw * 0.5f) + (sw * 0.5f) * vx / vw;
    out.Y = (sh * 0.5f) - (sh * 0.5f) * vy / vw;
    return true;
}
