// read_write.c 片段：内核态读写目标进程
NTSTATUS ReadProcessMemoryKernel(HANDLE hProcess, PVOID lpBase, PVOID lpBuffer, SIZE_T nSize, PSIZE_T lpRead)
{
    KAPC_STATE apc;
    KeStackAttachProcess(hProcess, &apc);
    NTSTATUS st = STATUS_SUCCESS;
    __try {
        ProbeForRead(lpBuffer, nSize, 1);
        RtlCopyMemory(lpBuffer, lpBase, nSize);
    } __except (EXCEPTION_EXECUTE_HANDLER) { st = GetExceptionCode(); }
    KeUnstackDetachProcess(&apc);
    if (NT_SUCCESS(st) && lpRead) *lpRead = nSize;
    return st;
}

NTSTATUS WriteProcessMemoryKernel(HANDLE hProcess, PVOID lpBase, PVOID lpBuffer, SIZE_T nSize, PSIZE_T lpWritten)
{
    KAPC_STATE apc;
    KeStackAttachProcess(hProcess, &apc);
    NTSTATUS st = STATUS_SUCCESS;
    __try {
        ProbeForWrite(lpBase, nSize, 1);
        RtlCopyMemory(lpBase, lpBuffer, nSize);
    } __except (EXCEPTION_EXECUTE_HANDLER) { st = GetExceptionCode(); }
    KeUnstackDetachProcess(&apc);
    if (NT_SUCCESS(st) && lpWritten) *lpWritten = nSize;
    return st;
}
