static NTSTATUS DoCopy(PEPROCESS target, ULONGLONG src, PVOID dst, ULONG size, BOOLEAN toTarget) {
    SIZE_T done = 0;
    KAPC_STATE apc;
    NTSTATUS st;

    if (!target || !dst || !size) return STATUS_INVALID_PARAMETER;
    if (src == 0 || src + size < src) return STATUS_INVALID_PARAMETER;

    KeStackAttachProcess(target, &apc);
    __try {
        ProbeForRead((PVOID)(ULONG_PTR)(toTarget ? (ULONGLONG)dst : src), size, 1);
