// ue4_core.h  ——  Windows x64 外部读写基础
#include <windows.h>
#include <cstdio>
#include <vector>
#include <string>
#include <cstdint>

static HANDLE  g_hProc = nullptr;
static uint64_t g_modBase = 0;
static uint32_t g_modSize = 0;

static bool OpenTarget(const wchar_t* procName) {
    // 进程名占位符 [进程名]，例如 L"GameClient-Win64-Shipping.exe"
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return false;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (!_wcsicmp(pe.szExeFile, procName)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    if (!pid) return false;
    g_hProc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    return g_hProc != nullptr;
}

static bool ReadMem(uint64_t addr, void* buf, size_t size) {
    SIZE_T got = 0;
    return ReadProcessMemory(g_hProc, (LPCVOID)addr, buf, size, &got) && got == size;
}
static bool WriteMem(uint64_t addr, const void* buf, size_t size) {
    SIZE_T put = 0;
    return WriteProcessMemory(g_hProc, (LPVOID)addr, buf, size, &put) && put == size;
}

static bool GetModuleRange(const wchar_t* modName, uint64_t& base, uint32_t& size) {
    // 模块名占位符 [模块名]，UE4 通常就是主 exe
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, GetProcessId(g_hProc));
    if (snap == INVALID_HANDLE_VALUE) return false;
    MODULEENTRY32W me{ sizeof(me) };
    bool ok = false;
    if (Module32FirstW(snap, &me)) {
        do {
            if (!_wcsicmp(me.szModule, modName)) {
                base = (uint64_t)me.modBaseAddr; size = me.modBaseSize; ok = true; break;
            }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    g_modBase = base; g_modSize = size;
    return ok;
}
