```cpp
// 在 [base, base+size) 里搜 AOB，返回首个命中的虚拟地址
static uint64_t ScanAOB(uint64_t start, uint32_t size, const uint8_t* pat, const char* mask, size_t len) {
    std::vector<uint8_t> buf(size);
    if (!ReadMem(start, buf.data(), size)) return 0;
    for (size_t i = 0; i + len <= size; ++i) {
        bool hit = true;
        for (size_t j = 0; j < len; ++j)
            if (mask[j] == 'x' && buf[i + j] != pat[j]) { hit = false; break; }
        if (hit) return start + i;
    }
    return 0;
}

// 把 RIP 相对寻址的 mov [rip+disp32] 解析成绝对地址
static uint64_t RipResolve(uint64_t insnAddr, size_t insnLen, int32_t disp) {
    return insnAddr + insnLen + disp;
}
