## 2. 物理地址页表遍历（内核态，4 级页表 x64）

```c
// 读物理地址：把物理页映射成虚拟地址再读
// 已映射在 \Device\PhysicalMemory 不可直接 OpenProcess 的时代用 MmMapIoSpace
// 本骨架走 MmMapIoSpace，注意 CR3 切走后 MmMapIoSpace 内部会用当前 CR3

#include <ntifs.h>

typedef struct _GVA_TO_GPA_INFO {
    ULONG64 Gva;
    ULONG64 Gpa;
    BOOLEAN Valid;
} GVA_TO_GPA_INFO;

// 从当前 CR3 读 4 级表，只用于「当前进程」虚拟地址→物理地址
// 要读目标进程的任意虚拟地址，需先 __writecr3(target_cr3) 再调用
static ULONG64 ReadPhysicalU64(ULONG64 Pa)
{
    PHYSICAL_ADDRESS pa;
    pa.QuadPart = Pa & ~0xFFFULL;
    PVOID mapped = MmMapIoSpace(pa, PAGE_SIZE, MmNonCached);
    if (!mapped) return 0;
    ULONG64 v = *(PULONG64)((PUCHAR)mapped + (Pa & 0xFFF));
    MmUnmapIoSpace(mapped, PAGE_SIZE);
    return v;
}

// 假设调用前已 __writecr3(target_cr3)
static BOOLEAN VtopCr3(ULONG64 Va, PULONG64 OutPa)
{
    ULONG64 cr3 = __readcr3() & ~0xFFFULL;

    // PML4
    ULONG64 pml4e = ReadPhysicalU64(cr3 + ((Va >> 39) & 0x1FF) * 8);
    if (!(pml4e & 1)) return FALSE;

    // PDPT
    ULONG64 pdpte = ReadPhysicalU64((pml4e & 0x000FFFFFFFFFF000ULL) + ((Va >> 30) & 0x1FF) * 8);
    if (!(pdpte & 1)) return FALSE;

    // 1GB 大页
    if (pdpte & (1ULL << 7)) {
        *OutPa = (pdpte & 0x000FFFFFC0000000ULL) + (Va & 0x3FFFFFFF);
        return TRUE;
    }

    // PD
    ULONG64 pde = ReadPhysicalU64((pdpte & 0x000FFFFFFFFFF000ULL) + ((Va >> 21) & 0x1FF) * 8);
    if (!(pde & 1)) return FALSE;

    // 2MB 大页
    if (pde & (1ULL << 7)) {
        *OutPa = (pde & 0x000FFFFFFFE00000ULL) + (Va & 0x1FFFFF);
        return TRUE;
    }

    // PT
    ULONG64 pte = ReadPhysicalU64((pde & 0x000FFFFFFFFFF000ULL) + ((Va >> 12) & 0x1FF) * 8);
    if (!(pte & 1)) return FALSE;

    *OutPa = (pte & 0x000FFFFFFFFFF000ULL) + (Va & 0xFFF);
    return TRUE;
}
```

