kmbox 串口走的是 USB CDC 虚拟串口，主机侧就是个标准 COM 口，波特率随便填（实际按 USB 全速跑，115200 只是惯例）。下面是 KMBox Net/Pro 系（`kmbox.dll` 同一套命令字）的协议实现。

## 1. 帧格式

最常用的是 **8 字节鼠标帧**，固定结构：

```
字节0: 0x04        命令字 = 鼠标移动
字节1: 0x00        保留 / 润饰位
字节2: buttons     按键位: bit0 左键, bit1 右键, bit2 中键, bit3 侧键1, bit4 侧键2
字节3: x_low       相对位移 X 低字节 (int16, 小端)
字节4: x_high      X 高字节
字节5: y_low       相对位移 Y 低字节
字节6: y_high      Y 高字节
字节7: wheel       滚轮 int8
```

键盘是 11 字节帧，首字节 `0x03`，后面跟 8 字节 HID 键盘报文（modifier + 6 键位 + 保留）+ 尾字节。

## 2. 最简可用发送代码（Windows，无 DLL 依赖）

```cpp
#include <windows.h>
#include <cstdint>

class KmBoxSerial {
    HANDLE h = INVALID_HANDLE_VALUE;
public:
    bool Open(const wchar_t* comPort) {
        h = CreateFileW(comPort, GENERIC_READ | GENERIC_WRITE, 0, nullptr,
                        OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
        if (h == INVALID_HANDLE_VALUE) return false;
        DCB dcb{}; dcb.DCBlength = sizeof(dcb);
        GetCommState(h, &dcb);
        dcb.BaudRate = 115200;
        dcb.ByteSize = 8;
        dcb.Parity   = NOPARITY;
        dcb.StopBits = ONESTOPBIT;
        dcb.fBinary  = TRUE;
        dcb.fOutxCtsFlow = FALSE;
        dcb.fOutxDsrFlow = FALSE;
        dcb.fDtrControl  = DTR_CONTROL_DISABLE;
        dcb.fRtsControl  = RTS_CONTROL_DISABLE;
        SetCommState(h, &dcb);
        return true;
    }

    // dx, dy: -32768..32767 的相对位移；btn: 按键位；wheel: 滚轮
    bool MouseMove(int16_t dx, int16_t dy, uint8_t btn = 0, int8_t wheel = 0) {
        uint8_t f[8];
        f[0] = 0x04;
        f[1] = 0x00;
        f[2] = btn;
        f[3] = (uint8_t)(dx & 0xFF);
        f[4] = (uint8_t)((dx >> 8) & 0xFF);
        f[5] = (uint8_t)(dy & 0xFF);
        f[6] = (uint8_t)((dy >> 8) & 0xFF);
        f[7] = (uint8_t)wheel;
        DWORD written = 0;
        return WriteFile(h, f, 8, &written, nullptr) && written == 8;
    }

    bool MouseButton(uint8_t btn, int8_t wheel = 0) {
        return MouseMove(0, 0, btn, wheel);   // 位移 0 即纯按键事件
    }

    void Close() { if (h != INVALID_HANDLE_VALUE) CloseHandle(h); }
};
```

