```c
// x64 MSVC，需以管理员运行；链接无需额外库
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

typedef struct { DWORD pid; ULONG_PTR base; } MODINFO;

static BOOL get_modinfo(const wchar_t* proc, const wchar_t* mod, MODINFO* out) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return FALSE;
    PROCESSENTRY32W pe = { .dwSize = sizeof(pe) };
    if (!Process32FirstW(snap, &pe)) { CloseHandle(snap); return FALSE; }
    do {
        if (_wcsicmp(pe.szExeFile, proc) == 0) { out->pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    if (!out->pid) return FALSE;

    HANDLE ms = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, out->pid);
    if (ms == INVALID_HANDLE_VALUE) return FALSE;
    MODULEENTRY32W me = { .dwSize = sizeof(me) };
    if (Module32FirstW(ms, &me)) {
        do {
            if (_wcsicmp(me.szModule, mod) == 0) { out->base = (ULONG_PTR)me.modBaseAddr; break; }
        } while (Module32NextW(ms, &me));
    }
    CloseHandle(ms);
    return out->base != 0;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = (argc > 1) ? argv[1] : L"[进程名].exe";
    const wchar_t* mod  = (argc > 2) ? argv[2] : L"[模块名].dll";

    MODINFO mi = {0};
    if (!get_modinfo(proc, mod, &mi)) { wprintf(L"模块定位失败\n"); return 1; }
    wprintf(L"pid=%lu base=0x%llX\n", mi.pid, (unsigned long long)mi.base);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, mi.pid);
    if (!h) { wprintf(L"OpenProcess=%lu\n", GetLastError()); return 1; }

    // 多级指针链解析：链 [] 里填从模块基址开始的一串偏移，末项是最终字段偏移
    ULONG_PTR chain[] = { 0x[偏移1], 0x[偏移2], 0x[偏移3] };
    ULONG_PTR addr = mi.base;
    for (size_t i = 0; i < sizeof(chain)/sizeof(chain[0]) - 1; ++i) {
        ULONG_PTR next = 0;
        if (!ReadProcessMemory(h, (LPCVOID)(addr + chain[i]), &next, sizeof(next), NULL)) {
            wprintf(L"链断在第 %zu 级\n", i); CloseHandle(h); return 1;
        }
        addr = next;
    }
    addr += chain[sizeof(chain)/sizeof(chain[0]) - 1];

    int value = 0;
    if (!ReadProcessMemory(h, (LPCVOID)addr, &value, sizeof(value), NULL)) {
        wprintf(L"读最终字段失败=%lu\n", GetLastError());
    } else {
        wprintf(L"addr=0x%llX value=%d\n", (unsigned long long)addr, value);
    }
    CloseHandle(h);
    return 0;
}
